package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen0Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaping = new NumericEntityUnescaper();
        writer = new StringWriter();
    }

    private static class NumericEntityUnescaper extends org.apache.commons.lang3.text.translate.NumericEntityUnescaper {
        // This allows us to test the exact implementation provided in the prompt
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        String input = "abc";
        int result = unescaper.translate(input, 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_DecimalEntity() throws IOException {
        String input = "&#123;";
        // index 0: '&', index 1: '#'
        // start = 2 ('1'), end = 5 (';')
        // isHex = false
        // entityValue = 123
        // return = 2 + (5 - 2) + 0 + 1 = 6? 
        // Let's trace: start=2, end=5. (end-start)=3. 2 + 3 + 0 + 1 = 6.
        // Length of "&#123;" is 6. Correct.
        int result = unescaper.translate(input, 0, writer);
        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }

    @Test
    public void testTranslate_HexEntityLowercase() throws IOException {
        String input = "&#x1A;";
        // index 0: '&', index 1: '#'
        // start = 2 ('x'), isHex = true, start becomes 3 ('1')
        // end = 5 (';')
        // entityValue = Integer.parseInt("1A", 16) = 26
        // return = 2 + (5 - 3) + 1 + 1 = 6.
        // Length of "&#x1A;" is 6. Correct.
        int result = unescaper.translate(input, 0, writer);
        assertEquals(6, result);
        assertEquals(String.valueOf((char) 26), writer.toString());
    }

    @Test
    public void testTranslate_HexEntityUppercase() throws IOException {
        String input = "&#XFF;";
        // start = 2 ('X'), isHex = true, start becomes 3 ('F')
        // end = 5 (';')
        // entityValue = 255
        // return = 2 + (5 - 3) + 1 + 1 = 6.
        int result = unescaper.translate(input, 0, writer);
        assertEquals(6, result);
        assertEquals(String.valueOf((char) 255), writer.toString());
    }

    @Test
    public void testTranslate_NumberFormatExceptionDecimal() throws IOException {
        String input = "&#ABC;"; // Not a decimal
        int result = unescaper.translate(input, 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_NumberFormatExceptionHex() throws IOException {
        String input = "&#xG1;"; // G is not hex
        int result = unescaper.translate(input, 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testTranslate_IndexOutOfBounds_AtEnd() throws IOException {
        String input = "&";
        // This triggers input.charAt(index + 1) which is out of bounds
        unescaping.translate(input, 0, writer);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testTranslate_IndexOutOfBounds_NoSemicolon() throws IOException {
        String input = "&#123"; // Missing semicolon
        unescaping.translate(input, 0, writer);
    }

    @Test
    public void testTranslate_PartialMatchAtEnd() throws IOException {
        String input = "test&#123;";
        int result = unescaper.translate(input, 4, writer);
        assertEquals(6, result);
        assertEquals(String.valueOf((char) 123), writer.toString());
    }
}
